        @"^\s*(?:(?:hÃ£y|giÃºp mÃ¬nh|giÃºp tÃ´i)\s+)?(?:Ä‘áº·t|táº¡o|thÃªm|lÃªn)\s+(?:lá»‹ch|sá»± kiá»‡n)\b[^\r\n]*\bGoogle Calendar\b",
